  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Constantine, the New Rome and the Age of Justinian$j$, $j${"readings": [{"title": "Romans 13 (King James Version)", "url": "/portal/bible/Romans/13"}], "body": "When the Western Roman Empire fell in 476, the Eastern half lived on for nearly a thousand years. We call it the Byzantine Empire. Its capital was Constantinople, built by the Emperor Constantine and dedicated in 330 on the old city of Byzantium, where Europe meets Asia on the Bosporus. People called it the New Rome.\n\nWhy was the location so strong? The city sat on a great trade crossing, had harbors, and was protected by water and thick walls. At its height the empire reached around the eastern Mediterranean, including Greece, Asia Minor, Egypt and parts of Italy and North Africa.\n\nThe Byzantines carried on much from Rome: Roman law, roads, a strong central government and the Roman title of emperor. Yet they spoke Greek and became centered on the Christian faith. The emperor ruled with great power and worked closely with the Church. Romans 13:1 says, Let every soul be subject unto the higher powers. For there is no power but of God: the powers that be are ordained of God.\n\nJustinian ruled from 527 to 565. With his wife Theodora, he rebuilt the capital after the Nika riot and built the Hagia Sophia, finished in 537. His general Belisarius won back parts of the West. Justinian also had Roman law gathered into the Justinian Code.\n\nYour task: (1) Tell where Constantinople was and why that site was strong. (2) Name two things the Byzantines kept from Rome. (3) Tell two achievements of Justinian.\n\nFlorida standards: SS.912.W.2.1, SS.912.W.2.2, SS.912.W.2.3, SS.912.W.2.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.2.1, SS.912.W.2.2, SS.912.W.2.3, SS.912.W.2.4", "script": "Welcome to Unit 2. Listen, when the Western Roman Empire fell in four seventy six, the Eastern half did not fall. It lived on for nearly a thousand years, and we call it the Byzantine Empire. Its capital was Constantinople, dedicated by Constantine in the year three thirty on the old city of Byzantium, right where Europe meets Asia on the Bosporus. People called it the New Rome.\n\nNow watch this. Why was that city so strong? It sat on a great trade crossing, it had harbors, and water and thick walls protected it. At its height the empire reached around the eastern Mediterranean, into Greece, Asia Minor, Egypt and parts of Italy and North Africa.\n\nLook at this. The Byzantines kept much from Rome. They kept Roman law, roads, a strong central government and the title of emperor. But they spoke Greek and became centered on the Christian faith. Romans thirteen and one says, Let every soul be subject unto the higher powers. For there is no power but of God: the powers that be are ordained of God.\n\nThe great emperor was Justinian, who ruled from five twenty seven to five sixty five. With his wife Theodora he rebuilt the capital after the Nika riot and built the Hagia Sophia, finished in five thirty seven. His general Belisarius won back parts of the West, and Justinian gathered Roman law into the Justinian Code.\n\nYour task today. Tell where Constantinople was and why it was strong. Name two things the Byzantines kept from Rome. And tell two achievements of Justinian. Take the four question check when you finish.\n\nRulers rise and fall, but God remains. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Constantine, the New Rome and the Age of Justinian$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Byzantine Gifts, Iconoclasm, the Great Schism and the Fall of 1453$j$, $j${"readings": [{"title": "Exodus 20 (King James Version)", "url": "/portal/bible/Exodus/20"}], "body": "Byzantium gave the world lasting gifts. It preserved Greek and Roman writings by copying them in libraries and monasteries. It developed domed church architecture, brilliant mosaics and religious art. Its missionaries Cyril and Methodius brought the gospel to the Slavs and created an alphabet that led to the Cyrillic alphabet used in Russia and nearby lands. Byzantium also acted as a shield and trade bridge between Europe and Asia.\n\nTwo conflicts shaped the Church. First, the Iconoclast controversy, which began in the 720s under Emperor Leo III. Some leaders said that religious images, called icons, led to the worship of images and broke the command in Exodus 20:4, which says, Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth. Others said icons only honored the person shown and helped teach the faith. The dispute lasted until 843, when icons were restored.\n\nSecond, the Great Schism of 1054. Differences over the authority of the Pope, language and doctrine led the Church of Rome and the Church of Constantinople to excommunicate each other, dividing into the Roman Catholic and Eastern Orthodox churches.\n\nByzantium weakened through wars with Persians, Arabs and Turks and through the sack of Constantinople in 1204 by Crusaders. In 1453 the Ottoman sultan Mehmed II took the city with cannon, ending the empire.\n\nYour task: (1) Name two Byzantine contributions. (2) Explain the two sides of the Iconoclast debate. (3) Tell what happened in 1054 and in 1453.\n\nFlorida standards: SS.912.W.2.5, SS.912.W.2.6, SS.912.W.2.7, SS.912.W.2.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.2.5, SS.912.W.2.6, SS.912.W.2.7, SS.912.W.2.8", "script": "Welcome back. Listen, Byzantium gave the world lasting gifts. It preserved Greek and Roman writings by copying them in libraries and monasteries. It developed the great domed church, the brilliant mosaic and sacred art. Two missionaries, Cyril and Methodius, carried the gospel to the Slavs and gave them an alphabet that led to the Cyrillic writing used in Russia and nearby lands. And Byzantium stood as a shield and a trade bridge between Europe and Asia.\n\nNow watch this. Two conflicts shaped the Church. The first was the Iconoclast controversy, beginning in the 720s under Emperor Leo the Third. Some leaders said icons, the sacred images, led people toward worshipping images and broke the command in Exodus twenty and four, Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth. Others said icons only honored the person shown and helped teach the faith. The dispute lasted until eight forty three, when icons were restored.\n\nLook at this. The second was the Great Schism of ten fifty four. Differences over the authority of the Pope, language and doctrine led Rome and Constantinople to excommunicate each other, and the Church divided into the Roman Catholic and the Eastern Orthodox churches.\n\nThen came the decline. Wars with Persians, Arabs and Turks, and the sack of the city by Crusaders in twelve oh four, left Byzantium weak. In fourteen fifty three the Ottoman sultan Mehmed the Second took Constantinople with cannon, and the empire ended.\n\nYour task today. Name two Byzantine contributions, explain both sides of the icon debate, and tell what happened in ten fifty four and fourteen fifty three. Take the four question check.\n\nLet us hold the faith with humility and love. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Byzantine Gifts, Iconoclasm, the Great Schism and the Fall of 1453$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 The Rise of Islam and Three Faiths Compared$j$, $j${"readings": [{"title": "John 14 (King James Version)", "url": "/portal/bible/John/14"}], "body": "Islam began in Arabia in the 600s. Muhammad was born in Mecca around 570. Muslims believe he received revelations from God through the angel Gabriel, written in the Quran. In 622 he and his followers moved to Medina, a journey called the Hijra, which begins the Islamic calendar. He returned and took Mecca, and he died in 632.\n\nIslam teaches one God, called Allah in Arabic. Muslims follow the Five Pillars: the declaration of faith, prayer five times daily, giving to the poor, fasting during Ramadan and pilgrimage to Mecca. After Muhammad's death, disagreement over who should lead led to the division of Sunni and Shia Muslims.\n\nJudaism, Christianity and Islam all teach one God, honor Abraham and teach moral law and judgment. Yet they differ on key points. Judaism looks to the Hebrew Scriptures and awaits the Messiah. Christians confess that Jesus Christ is the Son of God, who died and rose again for our sins. Islam honors Jesus as a prophet but denies his deity and his crucifixion. John 14:6 says, Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.\n\nA good student describes other faiths fairly and respectfully, as they describe themselves, while holding firmly to the truth of the gospel.\n\nYour task: (1) Tell what the Hijra was. (2) List the Five Pillars. (3) Name two beliefs shared by Judaism, Christianity and Islam and one key difference.\n\nFlorida standards: SS.912.W.3.1, SS.912.W.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.1, SS.912.W.3.2", "script": "Welcome back. Listen, we now study one of the most important movements in world history. Islam began in Arabia in the six hundreds. Muhammad was born in Mecca around five seventy. Muslims believe God revealed the Quran to him through the angel Gabriel. In six twenty two he and his followers moved to Medina, a journey called the Hijra, and that year begins the Islamic calendar. He took Mecca later and died in six thirty two.\n\nNow watch this. Islam teaches one God, Allah in Arabic. Muslims follow five pillars. The declaration of faith, prayer five times a day, giving to the poor, fasting in the month of Ramadan, and pilgrimage to Mecca. After Muhammad died, a disagreement over who should lead gave rise to the Sunni and Shia branches.\n\nLook at this. Judaism, Christianity and Islam all teach one God, honor Abraham, and teach moral law and judgment. But they differ on key points. Judaism looks to the Hebrew Scriptures and awaits the Messiah. Christians confess that Jesus Christ is the Son of God who died and rose again for our sins. Islam honors Jesus as a prophet but denies his deity and his crucifixion. John fourteen and six says, Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.\n\nA good student describes other faiths fairly and respectfully, the way they describe themselves, while holding firmly to the truth of the gospel.\n\nYour task today. Tell what the Hijra was. List the five pillars. And name two shared beliefs and one key difference. Take the four question check when you finish.\n\nSpeak the truth in love. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 The Rise of Islam and Three Faiths Compared$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Islamic Expansion and the Golden Age$j$, $j${"readings": [{"title": "Proverbs 4 (King James Version)", "url": "/portal/bible/Proverbs/4"}], "body": "After 632, Arab armies led by caliphs, meaning successors, spread rapidly. They took Syria, Egypt and Persia and then North Africa, and in 711 they entered Spain. In 732 a Frankish army under Charles Martel stopped a raiding force near Tours in France. The Umayyad dynasty ruled from Damascus from 661 to 750. The Abbasid dynasty then ruled from the new capital of Baghdad, founded in 762.\n\nWhy did the spread succeed? Strong armies, weak neighbors, a common language and faith, trade routes and the use of local officials all helped. Many conquered peoples kept their faiths but paid a special tax. In India, Muslim rule came through the Delhi Sultanate beginning in 1206, and later the Mughal Empire, blending Islamic and Indian arts and ideas.\n\nThe Islamic Golden Age, roughly the 700s to 1200s, was a time of learning. In Baghdad's House of Wisdom, scholars translated Greek and other works. Al Khwarizmi helped develop algebra. Ibn Sina wrote the Canon of Medicine, used in Europe for centuries. Ibn al Haytham advanced the study of light and optics. Scholars improved the astrolabe, paper making, hospitals, and spread the number system from India that we now call Arabic numerals. Proverbs 4:7 says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.\n\nYour task: (1) Name the two dynasties and their capitals. (2) Give two reasons the empire spread. (3) Describe two achievements of the Golden Age.\n\nFlorida standards: SS.912.W.3.3, SS.912.W.3.4, SS.912.W.3.5, SS.912.W.3.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.3, SS.912.W.3.4, SS.912.W.3.5, SS.912.W.3.6", "script": "Welcome back. Listen, after the year six thirty two, Arab armies led by caliphs, which means successors, spread with great speed. They took Syria, Egypt and Persia, then North Africa, and in seven eleven they entered Spain. In seven thirty two a Frankish army under Charles Martel stopped a raiding force near Tours in France. The Umayyad dynasty ruled from Damascus. Then the Abbasids ruled from the new capital of Baghdad, founded in seven sixty two.\n\nNow watch this. Why did the spread succeed? Strong armies, weak neighbors, a shared language and faith, trade routes and the use of local officials all helped. Many conquered people kept their faiths but paid a special tax. In India, Muslim rule came through the Delhi Sultanate beginning in twelve oh six, and later the Mughal Empire, which blended Islamic and Indian art and ideas.\n\nLook at this. The Golden Age of Islam, roughly the seven hundreds to the twelve hundreds, was a time of learning. In the House of Wisdom in Baghdad scholars translated Greek and other works. Al Khwarizmi helped develop algebra. Ibn Sina wrote the Canon of Medicine, used in Europe for centuries. Ibn al Haytham advanced the study of light. Scholars improved the astrolabe, paper making and hospitals, and they spread the Indian number system we call Arabic numerals.\n\nProverbs four and seven says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.\n\nYour task today. Name two dynasties and their capitals. Give two reasons the empire spread. And describe two achievements of the Golden Age. Take the four question check.\n\nLearning honors the God who made the mind. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Islamic Expansion and the Golden Age$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Byzantium and Islam Compared$j$, $j${"prompt": "Write a clear report comparing the Byzantine Empire and the early Islamic world. Use complete sentences and label each part. Proverbs 4:7 says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.\n\nPart 1: Describe the location and strength of Constantinople and name two achievements of Justinian.\nPart 2: Explain what the Byzantines kept from Rome and what made them different.\nPart 3: Explain the Iconoclast controversy, the Great Schism of 1054 and the fall of Constantinople in 1453, and tell one lasting effect of each.\nPart 4: Explain the origins of Islam, the Five Pillars, and one way Judaism, Christianity and Islam are alike and one way they differ, speaking respectfully.\nPart 5: Describe how Islam spread, including one reason for success and one place where it met resistance.\nPart 6: Choose two contributions of the Golden Age and explain how each changed life in later centuries.", "rubric": "70 points. Constantinople and Justinian: 10 points. Rome kept and changed: 8 points. Iconoclasm, Schism and fall: 14 points. Origins and three faiths compared: 14 points. Spread of Islam: 8 points. Golden Age contributions: 12 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Byzantium and Islam Compared$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Faith, Learning and Power$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why Constantinople was important to world history, (2) tells how Byzantine and Islamic scholars preserved and added to human knowledge, (3) describes how a Christian student can discuss another faith fairly while holding to the truth of the gospel, and (4) connects your answer to Romans 13:1, which says, Let every soul be subject unto the higher powers. For there is no power but of God: the powers that be are ordained of God. Then write a respectful reply of at least 40 words to another student, or answer this question: Why do you think icons caused such a deep dispute? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Faith, Learning and Power$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Constantine, the New Rome and the Age of Justinian$j$, $j${"questions": [{"q": "Constantinople was built on the site of the old city of:", "options": ["Athens", "Byzantium", "Alexandria", "Carthage"]}, {"q": "The Byzantine Empire was the:", "options": ["Eastern half of the Roman Empire that lasted after 476", "Empire of Persia", "Western Empire", "Empire of Charlemagne"]}, {"q": "Which emperor built the Hagia Sophia and gathered Roman law?", "options": ["Charlemagne", "Justinian", "Constantine", "Augustus"]}, {"q": "The main language of the Byzantine Empire was:", "options": ["Old English", "Greek", "Arabic", "Persian"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Constantine, the New Rome and the Age of Justinian$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,1}'::int[], array[$j$Constantine rebuilt Byzantium as the New Rome.$j$,$j$The East survived the fall of the West.$j$,$j$Justinian finished the Hagia Sophia in 537 and ordered the Justinian Code.$j$,$j$Though they kept Roman ways, the Byzantines spoke Greek.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Constantine, the New Rome and the Age of Justinian$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Byzantine Gifts, Iconoclasm, the Great Schism and the Fall of 1453$j$, $j${"questions": [{"q": "Cyril and Methodius are remembered for:", "options": ["Bringing the gospel and a writing system to the Slavs", "Writing the Justinian Code", "Building the Hagia Sophia", "Leading the Crusades"]}, {"q": "The Iconoclast controversy was a dispute over:", "options": ["The calendar", "The Roman Senate", "The price of grain", "The use of religious images"]}, {"q": "The Great Schism of 1054 divided:", "options": ["Greek and Persian armies", "Sunni and Shia Muslims", "England and France", "Western Catholic and Eastern Orthodox Christians"]}, {"q": "Constantinople fell in 1453 to the:", "options": ["Vikings", "Ottoman Turks led by Mehmed II", "Mongols", "Franks"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Byzantine Gifts, Iconoclasm, the Great Schism and the Fall of 1453$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,1}'::int[], array[$j$Their work led to the Cyrillic alphabet.$j$,$j$Iconoclast means image breaker.$j$,$j$Rome and Constantinople excommunicated each other.$j$,$j$Mehmed II used cannon to break the walls.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Byzantine Gifts, Iconoclasm, the Great Schism and the Fall of 1453$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The Rise of Islam and Three Faiths Compared$j$, $j${"questions": [{"q": "The Hijra was Muhammad's journey in 622 from:", "options": ["Medina to Rome", "Cairo to Baghdad", "Jerusalem to Mecca", "Mecca to Medina"]}, {"q": "The holy book of Islam is the:", "options": ["Septuagint", "Quran", "Code of Justinian", "Talmud"]}, {"q": "Which is one of the Five Pillars of Islam?", "options": ["Building a temple", "Baptism", "Communion", "Fasting during Ramadan"]}, {"q": "Judaism, Christianity and Islam all teach:", "options": ["There is one God", "No moral law exists", "The Torah is not holy", "Jesus is a prophet only"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Rise of Islam and Three Faiths Compared$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,3,0}'::int[], array[$j$It marks the start of the Islamic calendar.$j$,$j$Muslims hold that the Quran was revealed to Muhammad.$j$,$j$The pillars are faith, prayer, giving, fasting and pilgrimage.$j$,$j$All three are monotheistic faiths that honor Abraham.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Rise of Islam and Three Faiths Compared$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Islamic Expansion and the Golden Age$j$, $j${"questions": [{"q": "The Abbasid capital, founded in 762, was:", "options": ["Cordoba", "Baghdad", "Mecca", "Damascus"]}, {"q": "The 732 battle near Tours halted a Muslim advance into:", "options": ["Western Europe through France", "Egypt", "India", "Japan"]}, {"q": "Al Khwarizmi is known for helping to develop:", "options": ["The compass rose only", "The printing press", "Algebra", "Gunpowder"]}, {"q": "The Delhi Sultanate was an early Muslim state in:", "options": ["Persia", "Spain", "Egypt", "India"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Islamic Expansion and the Golden Age$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,3}'::int[], array[$j$Baghdad became a center of trade and learning.$j$,$j$Charles Martel's Franks stopped the raid.$j$,$j$His work gave us the word algebra.$j$,$j$It began in 1206 and was followed by the Mughal Empire.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Islamic Expansion and the Golden Age$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Byzantine Empire and the Rise of Islam$j$, $j${"questions": [{"q": "Constantinople became the capital of the Eastern Empire under:", "options": ["Constantine", "Mehmed II", "Charles Martel", "Justinian only"]}, {"q": "The Justinian Code was a collection of:", "options": ["Medieval songs", "Islamic prayers", "Greek plays", "Roman law"]}, {"q": "The Eastern Orthodox and Roman Catholic churches divided in:", "options": ["1453", "622", "476", "1054"]}, {"q": "The Ottomans captured Constantinople in:", "options": ["732", "1054", "330", "1453"]}, {"q": "The Islamic calendar begins with the:", "options": ["Founding of Baghdad", "Birth of Muhammad", "Hijra in 622", "Fall of Rome"]}, {"q": "Sunni and Shia Muslims first divided over:", "options": ["Who should lead after Muhammad", "The date of Ramadan", "The Hagia Sophia", "Roman law"]}, {"q": "Baghdad's House of Wisdom was a center for:", "options": ["Printing Bibles", "Building cathedrals", "Training Viking sailors", "Translating and studying knowledge"]}, {"q": "Which is a key Christian difference from Islam?", "options": ["Christians confess Jesus as the Son of God who rose again", "Christians honor no scripture", "Christians reject Abraham", "Christians deny one God"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Byzantine Empire and the Rise of Islam$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,3,2,0,3,0}'::int[], array[$j$Constantine dedicated the city in 330.$j$,$j$Justinian had Roman law gathered and organized.$j$,$j$The Great Schism came in 1054.$j$,$j$Mehmed II ended the Byzantine Empire in 1453.$j$,$j$Year one is the year of the move to Medina.$j$,$j$The dispute was over succession.$j$,$j$Scholars there translated and expanded Greek and other works.$j$,$j$Christianity confesses the deity and resurrection of Christ.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Byzantine Empire and the Rise of Islam$j$ on conflict (item_id) do nothing;
